/* ----------------------------------------------------------------
   Polices embarquées pour le PDF du bordereau (/comptage), en base64.

   Sous-ensembles TTF tirés de Google Fonts (mêmes familles que le
   site), régénérables ainsi :

     pip install fonttools
     # récupérer les TTF via https://fonts.googleapis.com/css2?family=…
     # (agent utilisateur non-woff2 pour obtenir les URL .ttf), puis :
     pyftsubset bodoni.ttf --text="VESTIA " --no-hinting
     pyftsubset <famille>.ttf --no-hinting \
       --unicodes="U+0020-007E,U+00A0-00FF,U+0152-0153,U+2013-2014,U+2019,U+2026,U+2192"

   Bodoni Moda ne contient que les lettres du wordmark (≈ 2 Ko) ; les
   autres couvrent le français. Total ≈ 150 Ko de TTF (≈ 200 Ko en
   base64), embarqués dans le bundle de la page et dans chaque PDF.
---------------------------------------------------------------- */

/* Bodoni Moda — wordmark VESTIA seulement */
export const POLICE_BODONI = '';

/* Libre Baskerville — numéro de bordereau et montant */
export const POLICE_BASKERVILLE = '';

/* Libre Baskerville italique — mentions et signature de marque */
export const POLICE_BASKERVILLE_ITALIQUE = '';

/* Montserrat 400 — texte courant */
export const POLICE_MONTSERRAT = '';

/* Montserrat 500 — libellés en petites capitales */
export const POLICE_MONTSERRAT_MEDIUM = '';
